from h import build
R=[
(3571404,"Cari de bœuf aux haricots verts",
"Charlie, cuisinier passionné ayant récemment reçu une greffe de rein, nous a aidés à adapter cette recette pour la Kidney Kitchen.",
"4 portions pour adultes",None,
["2 cuillères à soupe d'huile","2 cuillères à café de cumin en poudre","500 g de bifteck à braiser, coupé en dés","30 g de beurre non salé OU 2 cuillères à soupe d'huile d'olive","1 cuillère à café de curcuma","1 boîte de 400 g de tomates concassées","½ cuillère à café de graines de fenugrec","Poivre noir pour assaisonner","2 gros oignons, hachés","6 gousses d'ail, écrasées","1 cuillère à café de piment en poudre","1 morceau de gingembre de 5 cm, finement râpé","2 cuillères à café de coriandre moulue","1 cuillère à café de sucre","100 g de haricots verts (surgelés ou frais, parés)","2 cuillères à soupe de crème épaisse (facultatif)","2 cuillères à café de garam masala","½ petit bouquet de coriandre (10 g)","240 g de riz non cuit, rincé et égoutté"],
["Préchauffez le four à 160 °C / 140 °C chaleur tournante / thermostat gaz 3. Faites chauffer 1 cuillère à soupe d'huile dans une cocotte à feu moyen-vif. Assaisonnez le bœuf de poivre noir et faites-le dorer dans la cocotte 5 à 8 minutes, en le retournant avec une pince à mi-cuisson, jusqu'à ce qu'il soit uniformément doré. Mettez de côté.","Dans la même cocotte, pour ne pas perdre les saveurs, faites chauffer le reste de l'huile ou le beurre, puis ajoutez les oignons et les graines de fenugrec. Faites revenir doucement 15 minutes, ou jusqu'à ce qu'ils soient dorés et caramélisés. Ajoutez l'ail, le gingembre, le piment, le curcuma, la coriandre moulue et le cumin et faites revenir 2 minutes. Ajoutez les tomates, puis remplissez la boîte vide d'eau et ajoutez-la au mélange. Répétez, de façon à ajouter l'équivalent de 2 boîtes d'eau. Incorporez le sucre et portez à frémissement.","Ajoutez le bœuf (ou les substituts de légumes), mettez un couvercle et faites cuire au four 1½ à 2 heures. Retirez le couvercle, ajoutez les haricots verts et faites cuire encore 20 minutes.","Faites cuire le riz selon les instructions sur l'emballage.","Incorporez le garam masala et la crème (le cas échéant) et rectifiez l'assaisonnement. Parsemez de coriandre et servez avec le riz cuit."],
[["Note du chef","Ce cari rempli de saveurs est un repas réconfortant et riche en énergie, faible en sel, en potassium et en phosphate, mais assez impressionnant pour être servi à des invités !"],["Conseils sur les portions pour les enfants","Les portions sont basées sur des portions d'adulte. Voici un guide pour les enfants :\nTout-petit (1 à 4 ans) : ¼ de portion d'adulte\nJeune enfant (5 à 9 ans) : ½ portion d'adulte\nEnfant plus âgé (10 à 13 ans) : ¾ de portion d'adulte\nAdolescents (14 ans et plus) : 1 portion d'adulte\nCertains enfants ont un appétit plus grand que d'autres. La portion de votre enfant pourrait devoir être adaptée à son alimentation habituelle si vous pensez que les portions recommandées sont trop grandes ou trop petites. Nous vous conseillons d'en parler avec votre diététiste avant d'augmenter la portion si votre enfant a de la difficulté à maîtriser son potassium ou son phosphate."],["Glucides","Le riz est la principale source de glucides, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Phosphate/potassium","Cette recette est faible en potassium si vous respectez les quantités des ingrédients et les tailles de portion. Elle est aussi faible en phosphate, mais elle en contient un peu, principalement provenant du bœuf; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines et convient aux personnes à qui l'on a conseillé de manger plus de protéines. Si on vous a conseillé de manger moins de protéines, essayez de réduire la quantité de bœuf de moitié et de la remplacer par une boîte de lentilles vertes ou brunes égouttées et rincées."],["Énergie","Pour les personnes qui ont besoin d'augmenter les calories de leurs repas, ajoutez plus de crème."],["Option plus saine","Si vous devez réduire les calories de ce plat, omettez la crème et utilisez moins d'huile. Pour augmenter les fibres de ce plat, réduisez le bœuf de moitié et remplacez-le par des lentilles vertes ou brunes."],["Conservation","Une fois cuit et refroidi, le cari peut être conservé dans un contenant hermétique au réfrigérateur et réchauffé le lendemain. Le riz se mange de préférence fraîchement préparé. Ne le réchauffez pas."]],
[]),
(3595044,"Beignets de betterave et de carotte",
"Un repas végétal riche en protéines.",
"4",None,
["200 g de farine de pois chiches (farine de gram)","200 g de betterave crue, pelée et râpée","200 g de carottes, pelées et râpées","8 oignons verts, hachés","1 cuillère à soupe d'huile d'olive",["Pour servir","80 g de feuilles de roquette"],["Pour servir","½ concombre, tranché"],["Pour servir","80 ml de yogourt de soja"],["Pour servir","Une petite poignée de persil, haché"],["Pour servir","4 petits pains croustillants"]],
["Préchauffez le four à 180 °C / 160 °C chaleur tournante / thermostat gaz 4. Mettez la farine de pois chiches (farine de gram) dans un bol et ajoutez la betterave, la carotte et les oignons. Mélangez pour bien combiner.","Ajoutez juste assez d'eau pour lier les ingrédients. Faites chauffer l'huile dans une poêle à feu moyen, divisez la pâte en huit beignets et déposez-les dans la poêle. Faites cuire 3 minutes, jusqu'à ce que le dessous commence à croustiller, puis retournez les beignets et faites cuire l'autre côté encore 3 minutes.","Transférez les beignets sur une plaque de cuisson et faites-les cuire au four 10 minutes. Pendant la cuisson des beignets, incorporez le persil haché au yogourt.","Sortez les beignets du four et servez deux beignets par portion avec la salade de roquette et de concombre, le yogourt et un petit pain croustillant."],
[["Note du chef","Un savoureux plat végane."],["Glucides","La farine de pois chiches (farine de gram) et le petit pain sont les principales sources de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium si vous respectez les quantités et les tailles de portion indiquées.\nCette recette est aussi faible en phosphate, mais elle en contient tout de même; par conséquent, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est riche en protéines, ce qui la rend adaptée aux personnes à qui l'on a conseillé de manger plus de protéines, en particulier celles sous dialyse."],["Sans gluten","Servez avec un petit pain sans gluten."],["Option plus saine","Utilisez un petit pain de blé entier plutôt que blanc pour augmenter les fibres de ce plat. Lorsque vous choisissez les petits pains, cherchez aussi ceux qui contiennent le moins de sel ajouté."],["Conservation","Ce plat se déguste de préférence fraîchement préparé."]],
[]),
(3596476,"Poulet aux amandes",
"Une recette familiale traditionnelle du sud de l'Inde.",
"2",None,
["1 cuillère à soupe de ghee (ou de beurre non salé)","1 petit oignon, râpé","2 gousses d'ail, écrasées ou finement hachées","1 morceau de gingembre de 2 cm, râpé ou finement haché","150 g de carottes, pelées et coupées en petits morceaux","1 cuillère à café de coriandre en poudre","1 cuillère à café de cumin en poudre","1 pincée de piment en poudre (plus si vous aimez)","30 g d'amandes moulues","200 g de haut de cuisse ou de poitrine de poulet désossé et sans peau, coupé en cubes de 2 cm","120 g de riz à grains longs ou basmati","100 g de petits pois surgelés","40 à 80 ml d'eau",["Pour servir","2 cuillères à soupe de coriandre fraîche, hachée"]],
["À feu vif, dans une poêle, faites fondre le ghee, puis ajoutez l'oignon râpé, l'ail, le gingembre, la carotte et les épices et faites cuire 10 minutes. Si le mélange commence à coller, ajoutez un peu d'eau.","Ajoutez les amandes moulues avec 40 ml d'eau dans la poêle. Si les ingrédients commencent à coller à la poêle, ajoutez plus d'eau (encore 20 à 40 ml).","Ajoutez les cubes de poulet dans la poêle, faites-les dorer, puis réduisez à feu moyen. Faites cuire 10 minutes, en ajoutant de l'eau au besoin pour empêcher la sauce de coller à la poêle.","Pendant ce temps, rincez le riz à l'eau froide et égouttez-le. Mettez-le dans une casserole d'eau bouillante, ramenez à ébullition, puis réduisez à feu moyen, couvrez et faites cuire 12 minutes.","Le poulet aux amandes est prêt lorsque le poulet est bien cuit et que la sauce est épaisse et de couleur sable. À ce stade, ajoutez les petits pois pour les réchauffer.","Servez le riz, garnissez de poulet aux amandes et décorez de coriandre fraîche hachée."],
[["Note du chef","Voici un plat crémeux, authentique et polyvalent, faible en sel, en potassium et en phosphate."],["Glucides","Le riz est la principale source de glucides de ce plat principal, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Ce plat est faible en potassium; si on vous a conseillé de réduire votre potassium, veillez à respecter les quantités et les tailles de portion indiquées.\nCette recette est faible en phosphate, mais elle en contient un peu; par conséquent, si on vous a prescrit un chélateur du phosphate, assurez-vous de le prendre avec ce plat."],["Protéines","Ce plat est riche en protéines et convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse. Si on vous a conseillé de manger moins de protéines, envisagez d'utiliser une boîte de 400 g de pois chiches égouttés à la place du poulet, ou réduisez la quantité de poulet de moitié (100 g) et remplacez-la par une boîte de 200 g de pois chiches ou de lentilles égouttés."],["Option plus économique","Envisagez d'utiliser du poulet avec les os et de le désosser vous-même. Omettez aussi la coriandre fraîche hachée pour réduire le coût. Si vous ne trouvez pas de cumin ou de coriandre moulus, vous pourriez les remplacer par de la poudre de cari."],["Végétarien","Remplacez le poulet par une boîte de 400 g de lentilles ou de pois chiches égouttés. Vous pouvez aussi utiliser 200 à 300 g de tofu."],["Végane","Remplacez le poulet par une boîte de 400 g de lentilles ou de pois chiches égouttés. Vous pouvez aussi utiliser 200 à 300 g de tofu. Remplacez le ghee par une huile végétale."],["Option plus saine","Remplacez le riz blanc par du riz brun à grains entiers pour augmenter les fibres et remplacez le ghee ou le beurre non salé par une huile végétale comme l'huile de tournesol pour une source de matières grasses plus saine. Toutefois, la sauce sera un peu plus liquide."],["Conservation","Cette sauce au cari se congèle bien. Laissez-la refroidir peu après la cuisson et congelez-la jusqu'à trois mois. Décongelez complètement au réfrigérateur avant de réchauffer."],["Astuces","Si vous préférez, d'autres légumes peuvent être utilisés à la place des petits pois et des carottes. Le chou-fleur et les haricots verts conviennent bien, tout comme l'aubergine et les épinards, mais ceux-ci sont riches en potassium; si vous devez réduire votre potassium, ne les choisissez donc pas."]],
[]),
(3643178,"Chili aux haricots sur patate douce au four",">","2",None,
["2 patates douces moyennes (120 g chacune)","1 gousse d'ail, écrasée","4 oignons verts, hachés","1 boîte de 400 g de haricots noirs, rincés et égouttés","10 g de concentré de tomate","½ cuillère à café de flocons de piment","1 cuillère à café de cumin moulu","½ cuillère à café de paprika fumé","30 g de maïs surgelé","2 cuillères à café d'huile d'olive",["Pour servir","40 g de crème sure"]],
["Préchauffez le four à 200 °C / chaleur tournante 180 °C / thermostat gaz 6. Piquez les patates douces de partout et frottez-les d'un peu d'huile d'olive. Faites cuire au four environ 40 minutes, jusqu'à ce qu'elles soient tendres.","Pendant la cuisson des patates, faites chauffer l'huile d'olive dans une poêle à feu moyen et faites revenir les oignons verts et l'ail jusqu'à ce qu'ils soient tendres.","Ajoutez les haricots noirs, le concentré de tomate, les flocons de piment, le cumin, le paprika et le maïs. Mélangez et faites cuire à feu doux 10 minutes.","Sortez les patates du four lorsqu'elles sont cuites et laissez-les reposer 5 minutes. Pour faire une ouverture, incisez la patate sur la longueur, écartez-la un peu et garnissez-la du mélange de haricots. Servez avec de la crème sure sur le dessus."],
[["Note du chef","Cette recette de chili aux haricots est une délicieuse option végétarienne, qui apporte beaucoup de fibres et de protéines."],["Glucides","La patate douce est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Malgré l'utilisation de certains ingrédients riches en potassium, comme les patates douces au four et le concentré de tomate, cette recette est faible en potassium si l'on respecte les quantités des ingrédients et les tailles de portion. Cette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par les haricots noirs; si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette est une source de protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines, comme celles sous dialyse."],["Option plus saine","Vous pourriez faire blanchir la patate douce avant de la rôtir pour réduire davantage la teneur en potassium."],["Conservation","Le mélange de haricots peut être préparé à l'avance et conservé dans un contenant hermétique au réfrigérateur jusqu'à 3 jours."]],
[]),
(3689346,"Riz frit aux crevettes à la caribéenne",
"Un plat rapide, facile et polyvalent, faible en sel, en potassium et en phosphate – n'hésitez pas à ajouter des légumes ou à les remplacer par d'autres, comme des petits pois ou du maïs.",
"4",None,
["300 g de riz à grains longs","2 cuillères à café d'huile végétale","1 oignon, finement haché","2 carottes, pelées et finement hachées","100 g de haricots verts, coupés","1 poivron rouge, haché","1 cuillère à soupe d'assaisonnement vert (ou 1 cuillère à café de fines herbes mélangées)","300 g de grosses crevettes crues et décortiquées (des crevettes déjà cuites peuvent être utilisées)","2 œufs, battus","1 à 2 cuillères à soupe de sauce soja à teneur réduite en sel","10 g de coriandre fraîche, hachée","4 oignons verts, hachés (facultatif)"],
["Faites cuire le riz selon les instructions sur l'emballage, ou dans un cuiseur à riz. Mettez de côté. Dans un bol, mettez les crevettes crues et l'assaisonnement vert ou les fines herbes, mélangez et laissez reposer pendant que vous réalisez l'étape 3 (si vous utilisez des crevettes cuites, sautez cette étape et ajoutez l'assaisonnement vert ou les herbes lorsque vous faites cuire le riz). Versez une cuillère à café d'huile dans une grande poêle ou un wok à feu moyen et ajoutez l'oignon, les carottes, les haricots verts et le poivron, remuez 2 à 5 minutes, puis couvrez jusqu'à ce que les légumes soient cuits. Une fois cuits, mettez les légumes de côté dans un bol.","Dans la même poêle, versez une cuillère à café d'huile et faites cuire les crevettes à feu doux. Faites-les sauter en les retournant régulièrement pendant 5 minutes jusqu'à ce qu'elles soient bien cuites. Retirez de la poêle et mettez de côté. Si vous utilisez des crevettes cuites, vous pouvez sauter cette étape.","Remettez les légumes dans la poêle à feu doux, en utilisant la même poêle avec le jus des crevettes. Faites un puits au centre des légumes, ajoutez l'œuf battu et brouillez-le avec les légumes.","Ajoutez la sauce soja, les crevettes cuites et le riz. Mélangez et faites cuire encore 2 minutes jusqu'à ce que le plat soit chaud. Augmentez le feu, ajoutez la coriandre et mélangez. Servez pour quatre personnes, en ajoutant des oignons verts hachés si désiré."],
[["Note du chef","Une version santé du riz frit aux crevettes à la caribéenne."],["Glucides","Le riz est la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Ce plat est très faible en potassium; il convient donc aux personnes à qui l'on a conseillé de réduire le potassium dans leur alimentation.\nCette recette est aussi faible en phosphate, mais elle en contient un peu, principalement fourni par les œufs et les crevettes; par conséquent, si on vous a prescrit un chélateur du phosphate, prenez-le comme indiqué."],["Protéines","Cette recette fournit une source de protéines; elle convient donc aux personnes à qui l'on a conseillé de manger plus de protéines."],["Option plus économique","Si les crevettes crues coûtent cher, vous pourriez utiliser des crevettes déjà cuites et sauter les étapes suggérées ci-dessus."],["Sans gluten","Utilisez une sauce soja sans gluten."],["Végétarien / Végane","Omettez les crevettes et remplacez-les par du tofu fumé."],["Option plus saine","Cette recette est faible en sel, car on a utilisé une sauce soja à teneur réduite en sel. Cependant, il s'agit tout de même d'un produit riche en sel; il est donc préférable de mesurer cet ingrédient soigneusement afin d'éviter un excès de sel."],["Conservation","Ce plat se déguste de préférence fraîchement préparé, car il n'est pas recommandé de réchauffer le riz, en particulier si vous avez reçu une greffe de rein."]],
[]),
(3702868,"Pâtes au four",
"Cette recette fonctionne avec n'importe quelle forme de pâtes que vous avez déjà, bien que l'orzo soit particulièrement bon.",
"2",None,
["1 cuillère à soupe d'huile végétale","½ petit oignon, pelé et haché","150 g de pâtes (l'orzo convient bien)","40 g de choux verts ou d'épinards surgelés","½ poivron, épépiné et haché","1 cuillère à café de fines herbes mélangées séchées","½ cuillère à café de flocons de piment (facultatif)","1 cuillère à soupe de concentré de tomate","1 boîte de 400 g de pois chiches (égouttés)","1 cube de bouillon de légumes à faible teneur en sel dilué dans de l'eau bouillante pour obtenir 150 ml","10 g de beurre non salé","20 g de cheddar, râpé"],
["Préchauffez le four à 180 °C. Dans une poêle allant au four, faites chauffer l'huile et ajoutez l'oignon. Faites cuire jusqu'à ce qu'il soit tendre. Dans une autre casserole, faites cuire les pâtes selon les instructions sur l'emballage.","Ajoutez les choux, le poivron, les herbes et le piment à l'oignon qui revient. Faites cuire à feu moyen 5 minutes, jusqu'à ce qu'ils soient tendres. Ajoutez le concentré de tomate et faites cuire encore une minute.","Ajoutez les pâtes cuites et égouttées, les pois chiches et le bouillon et portez à frémissement. Mettez un couvercle sur la poêle et enfournez 15 minutes.","Sortez du four, incorporez le beurre, râpez le fromage par-dessus et servez."],
[["Note du chef","Ce plat tout-en-un satisfaisant est faible en sel, en potassium et en phosphate."],["Glucides","Les pâtes sont la principale source de glucides de cette recette, et la valeur est fournie pour les personnes formées à l'ajustement de l'insuline."],["Potassium/phosphate","Cette recette est faible en potassium si l'on respecte les quantités des ingrédients et les tailles de portion; elle convient donc aux personnes à qui l'on a conseillé de suivre un régime pauvre en potassium.\nCette recette est aussi faible en phosphate, mais elle en contient un peu, fourni par les pois chiches et le fromage; par conséquent, si on vous a prescrit un chélateur du phosphate, vous devriez le prendre comme indiqué."],["Protéines","Cette recette contient des protéines. Si on vous a conseillé de réduire vos protéines, vous pouvez utiliser moins de fromage ou moins de pois chiches."],["Astuces","Ce plat fonctionne avec n'importe quelle forme de pâtes que vous avez déjà, bien que l'orzo soit particulièrement bon. Si vous préférez utiliser du riz à la place des pâtes, vous aurez peut-être besoin d'un peu plus de bouillon."],["Conservation","Ce plat se déguste de préférence tout de suite."]],
[]),
]
